-- Dados de exemplo, gerados a partir dos mocks do frontend. Só rodam no perfil dev.
-- Autores sem e-mail e sem senha: não conseguem fazer login.









UPDATE products p SET avg_score = s.avg, review_count = s.total
FROM (SELECT product_id, round(avg(score), 1) AS avg, count(*) AS total FROM reviews WHERE deleted_at IS NULL GROUP BY product_id) s
WHERE p.id = s.product_id;

-- Em bancos já criados, os contadores e o progresso voltam a refletir só o que é real
UPDATE reviews r SET
    like_count = (SELECT count(*) FROM review_likes l WHERE l.review_id = r.id),
    comment_count = (SELECT count(*) FROM comments c WHERE c.review_id = r.id AND c.deleted_at IS NULL);

-- Ainda não existe assinatura: ninguém é PRO
UPDATE users SET is_pro = false;

SELECT refresh_user_progress(id) FROM users;
