INSERT INTO reviews (user_id, product_id, title, body, score, cover_url, created_at) VALUES ((SELECT id FROM users WHERE username = 'anaflex'), (SELECT id FROM products WHERE slug = 'audeze-maxwell'), 'Audeze Maxwell: o endgame dos headsets sem fio', 'Os drivers planares magnéticos da Audeze chegam ao mundo dos headsets wireless com o Maxwell. A qualidade de áudio é absurdamente superior a qualquer headset dinâmico, e o microfone removível impressiona.', 9.5, 'https://images.unsplash.com/photo-1546435770-a3e426bf472b?w=1200&q=80', '2024-01-10') ON CONFLICT DO NOTHING;
INSERT INTO review_scores (review_id, criterion_id, value) VALUES ((SELECT id FROM reviews WHERE user_id = (SELECT id FROM users WHERE username = 'anaflex') AND product_id = (SELECT id FROM products WHERE slug = 'audeze-maxwell')), (SELECT c.id FROM criteria c JOIN categories k ON k.id = c.category_id WHERE k.slug = 'headset' AND c.label = 'Áudio'), 9.9) ON CONFLICT DO NOTHING;
